{"implementation":"def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    members = {}
    for node, comm in refinement.items():
        members.setdefault(comm, []).append(node)
    for comm in members:
        members[comm].sort()
    agg = {}
    for u, v, w in edges:
        cu = refinement[u]
        cv = refinement[v]
        a, b = (cu, cv) if cu <= cv else (cv, cu)
        agg[(a, b)] = agg.get((a, b), 0) + w
    aggregate_edges = [[a, b, w] for (a, b), w in agg.items()]
    aggregate_edges.sort(key=lambda x: (x[0], x[1]))
    return {'aggregate_edges': aggregate_edges, 'members': members}"}
